<script setup lang="ts">
import {ref} from 'vue'
const props=defineProps<{preview?:boolean;confirmed?:boolean;label?:string;disabled?:boolean;markers?:{id:number;name:string;x:number;y:number;selected?:boolean}[]}>()
const emit=defineEmits<{pick:[point:{x:number;y:number}];choose:[id:number]}>()
const point=ref({x:50,y:55})
function pick(event:MouseEvent){if(!props.preview||props.disabled)return;const box=(event.currentTarget as HTMLElement).getBoundingClientRect();point.value={x:Math.max(5,Math.min(95,(event.clientX-box.left)/box.width*100)),y:Math.max(8,Math.min(92,(event.clientY-box.top)/box.height*100))};emit('pick',{...point.value})}
function key(event:KeyboardEvent){if(!props.preview||props.disabled)return;const directions:Record<string,[number,number]>={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]};const delta=directions[event.key];if(delta){event.preventDefault();point.value={x:Math.max(5,Math.min(95,point.value.x+delta[0])),y:Math.max(8,Math.min(92,point.value.y+delta[1]))}}}
function keyboardPick(event:MouseEvent){if(event.detail===0&&props.preview&&!props.disabled)emit('pick',{...point.value})}
</script>
<template>
 <div class="dispatch-map-canvas" :class="{interactive:preview}">
  <div class="map-watermark">{{ preview?'Mock 交互预览 · 合成网格':'位置示意 · 非高德底图' }}</div>
  <div class="map-block block-one"></div><div class="map-block block-two"></div><div class="map-block block-three"></div><div class="map-park"></div><div class="road road-one"></div><div class="road road-two"></div><div class="road road-three"></div>
  <button v-if="preview" class="pick-surface" type="button" :disabled="disabled" aria-label="模拟地图选点：点击选点，或方向键移动后按回车" @click="($event.detail===0?keyboardPick:pick)($event)" @keydown="key"></button>
  <div v-if="preview" class="parking-pin" :class="{confirmed}" :style="{left:point.x+'%',top:point.y+'%'}"><span>P</span><small>{{ confirmed?'已确认模拟位置':'模拟停放位置' }}</small></div>
  <div v-else class="map-unavailable"><strong>{{ confirmed?'停车地址已确认':'先搜索并核对车辆停放地址' }}</strong><span>交互底图与地图选点尚未启用</span><span>当前可使用下方地址搜索；此图不表示真实位置或道路。</span></div>
  <button v-for="(marker,index) in (preview?markers:[])" :key="marker.id" class="shop-pin" :class="{selected:marker.selected}" :style="{left:marker.x+'%',top:marker.y+'%'}" :disabled="disabled" type="button" :aria-label="'在示意图选择'+marker.name" :aria-pressed="marker.selected" @click="emit('choose',marker.id)">{{ index+1 }}</button>
  <span class="map-caption">{{ preview?'点击与键盘操作仅改变合成预览，不代表真实经纬度':'真实地图功能待配置；不自动读取设备位置' }}</span>
 </div>
 <p class="map-address" role="status">{{ label||'尚未确认车辆当前停放位置' }}</p>
</template>
<style scoped>
.dispatch-map-canvas{height:290px;position:relative;isolation:isolate;overflow:hidden;background:#eef1eb;border:1px solid #dce4dc;border-radius:10px}.map-watermark{position:absolute;top:12px;left:12px;z-index:5;padding:5px 9px;background:#ffffffeb;color:#42554b;font-size:12px;border-radius:5px;pointer-events:none}.map-block{position:absolute;background:#e3e1e9;border:1px solid #d6d5df;border-radius:12px;transform:rotate(-12deg);width:22%;height:25%;pointer-events:none}.block-one{top:21%;left:10%}.block-two{top:16%;right:13%}.block-three{bottom:12%;right:18%}.map-park{position:absolute;inset:23% 34% 13% 38%;border-radius:35%;background:#cce3bd;pointer-events:none}.road{position:absolute;background:white;border-block:1px solid #d8ded6;width:130%;height:20px;left:-15%;pointer-events:none}.road-one{top:40%;transform:rotate(-17deg)}.road-two{top:57%;transform:rotate(28deg)}.road-three{left:43%;top:-20%;height:140%;width:18px;transform:rotate(10deg)}.pick-surface{position:absolute;inset:0;border:0;background:transparent;border-radius:8px;cursor:crosshair;z-index:2}.pick-surface:focus-visible{outline:3px solid #2d7256;outline-offset:-4px}.parking-pin{position:absolute;transform:translate(-50%,-100%);z-index:3;pointer-events:none}.parking-pin span{display:block;border:3px solid white;background:#397dcc;border-radius:50% 50% 50% 0;transform:rotate(-45deg);color:white;width:29px;height:29px;line-height:29px;text-align:center;font-weight:bold;box-shadow:0 2px 8px #263d4d33}.parking-pin small{display:block;position:absolute;top:38px;left:-40px;width:115px;text-align:center;background:#fffffff0;font-size:11px;border-radius:3px}.parking-pin.confirmed span{background:#2c7657}.shop-pin{position:absolute;z-index:4;border:2px solid white;transform:translate(-50%,-50%);border-radius:50%;background:#718578;color:white;width:32px;height:32px;font-weight:bold;box-shadow:0 2px 6px #253b3330}.shop-pin.selected{background:#2c7657;outline:3px solid #88bca1}.map-unavailable{position:absolute;z-index:1;inset:30% 10%;background:#fffffff2;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:9px;text-align:center;border-radius:10px;padding:15px;color:#42594d}.map-unavailable span{font-size:12px}.map-caption{position:absolute;z-index:5;bottom:8px;left:12px;font-size:11px;color:#4c5d54;background:#ffffffe8;padding:3px 7px;pointer-events:none}.map-address{margin:10px 0 0;font-size:13px;color:var(--color-text-secondary,#607269);line-height:1.6}@media(max-width:600px){.dispatch-map-canvas{height:240px}.map-unavailable{inset:28% 6%}.map-caption{max-width:85%}}
</style>
